    "sange_rhythm_title": "डेनिस लय र शब्दमा जोड (Stress Distribution)",
    "sange_rhythm_desc": "ठूला अक्षर र जोड चिह्न (accent) ले चिन्हित गरिएका अक्षरहरूले वाक्यहरूमा प्राकृतिक लयबद्ध जोड देखाउँछन् (जस्तै ”TÍD-lig MÁN-dag MÓR-gen”)। ध्यान दिनुहोस् कि कसरी गीतको लयले दैनिक डेनिस भाषाको प्राकृतिक उच्चारणको अनुसरण गर्दछ!",
    "sange_chorus_tag": "🌿 गीत-खेलको स्थायी कोरस (स्थायी अंश)",
