    "sange_chorus_youtube": "युट्युबमा धुन सुन्नुहोस्",
    "sange_verse_listen": "श्लोक (verse) सुन्नुहोस्",
    "sange_verse_note_1": "आधुनिक: \"når vi vasker vores tøj\" (आजकल हामी पुरानो vort को सट्टा vores भन्छौं)।",
    "sange_verse_note_2": "बारमा मुख्य जोड भएको ६/८ ताल: TÍRS-dag MÓR-gen।",
    "sange_verse_note_3": "उल्टो शब्द क्रम (Inversion) ध्यान दिनुहोस्: \"Så gør vi sådan\" (अघिल्लो भाग + क्रियापद + कर्ता)।",
    "sange_verse_note_4": "ऐतिहासिक रूपमा: म्याङ्गल बोर्ड र बेलना प्रयोग गरेर \"ruller vort tøj\"। आज: हामी कपडा पट्याएर राख्छौं।",
